<?php require_once __DIR__.'/../config.php';require_student();$pageTitle='Student dashboard';$s=db()->prepare('SELECT * FROM applications WHERE user_id=? ORDER BY created_at DESC');$s->execute([current_user()['id']]);$apps=$s->fetchAll();require __DIR__.'/../includes/header.php';?>
<section class="dashboard"><div class="container"><div class="dash-head"><div><div class="eyebrow">Student workspace</div><h1>Hello, <?= e(current_user()['name']) ?></h1><p>Manage your application and keep track of updates here.</p></div><a class="btn" href="<?= BASE_URL ?>/student/apply.php">New application</a></div><?php show_flash(); ?><div class="stat-grid"><div class="stat"><span>Total applications</span><strong><?= count($apps) ?></strong></div><div class="stat"><span>Under review</span><strong><?= count(array_filter($apps,fn($a)=>$a['status']==='Pending')) ?></strong></div><div class="stat"><span>Approved</span><strong><?= count(array_filter($apps,fn($a)=>$a['status']==='Approved')) ?></strong></div></div><div class="dash-card"><h2>My applications</h2><?php if(!$apps): ?><div class="empty-state"><strong>You have not applied yet</strong><span>When you submit an admission form, it will appear here.</span><p><a class="btn" href="<?= BASE_URL ?>/student/apply.php">Start an application</a></p></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Application ID</th><th>Programme</th><th>Submitted</th><th>Status</th><th>Admin note</th></tr></thead><tbody><?php foreach($apps as $a): ?><tr><td>CB-<?= str_pad((string)$a['id'],5,'0',STR_PAD_LEFT) ?></td><td><?= e($a['programme']) ?></td><td><?= e(date('d M Y',strtotime($a['created_at']))) ?></td><td><span class="badge <?= e($a['status']) ?>"><?= e($a['status']) ?></span></td><td><?= e($a['admin_note']?:'—') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div><div class="dash-card"><h2>Profile details</h2><p class="muted"><strong>Name:</strong> <?= e(current_user()['name']) ?> &nbsp; <strong>Email:</strong> <?= e(current_user()['email']) ?></p><p class="muted">Keep your registered email address active so you can receive admission updates.</p></div></div></section><?php require __DIR__.'/../includes/footer.php';?>
